referenceSolutions.javascript:
export function solve(row, rules) {
  return rules.every(
    (r) =>
      Object.hasOwn(row, r.key) &&
      (r.op === "equal" ? row[r.key] === r.value : row[r.key] >= r.value),
  );
}

